-- travel_paths: seed the Planes of Power routes (the Plane of Knowledge to every PoP zone, and back).
--
-- NOT applied yet (2026-10-29): ~94 KB is too large to pass through the Supabase MCP reliably. The guild lead pastes it
-- into the Supabase SQL Editor; then change this line to the date it was applied. Nothing reads the table yet: the plan
-- reads the same rows from web/lib/popTravel.ts.
--
-- travel_paths was created 2026-05-25 (20260525120000_initial_schema.sql) and has 0 rows. RLS is on with no policies,
-- so a web read of it needs the server key.
--
-- WHERE THE ROWS COME FROM: web/lib/popTravel.ts. Everything below the dashes is GENERATED from it by seedSql(), and
-- test/pop-travel.test.js fails when this file and the module disagree. Change the module, then regenerate:
--   node --experimental-strip-types -e "import('./web/lib/popTravel.ts').then(m => process.stdout.write(m.seedSql()))"
-- and replace everything under the dashes with the output.
--
-- Each hop carries its own citation in "src" (eqemu_doors / eqemu_zone_points rows, quest-script lines at
-- SecretsOTheP/quests ea0c766, server-source lines at eqmacemu 12068490) and an "unverified" note where the data does
-- not prove it. Locations are /loc order (y, x, z).
--
-- IDEMPOTENT. Row ids are uuid_generate_v5 over a stable key, so a re-run updates the same rows instead of adding
-- copies; it only ever touches rows with posted_by_discord_id null (these seed rows), never a member's own entry.
-- Every zone short name below exists in eqemu_zone (checked 2026-10-29).
-- ------------------------------------------------------------------------------------------------------------------
insert into travel_paths (id, zone_from_short, zone_to_short, hops, notes, posted_by_discord_id)
values
  (uuid_generate_v5(uuid_ns_url(), 'wolfpack:travel_paths:pop:fwd:poknowledge>potranquility'), 'poknowledge', 'potranquility',
$j$[
 {"type":"port","via":"book","from":"poknowledge","to":"potranquility","loc":{"y":-148,"x":-332,"z":-156},"arrive":{"y":774,"x":-1463,"z":-878},"gate":[{"kind":"level","text":"level 46: below it the book prints \"You are not yet experienced enough to pass through an inter-planar portal.\"","src":["poknowledge/player.lua:4-8 @ ea0c766"]}],"note":"Click the Plane of Tranquility book (the door POKPTPORT500). It lands you at the Tranquility arrival spot, beside the book that leads back.","src":["eqemu_doors zone=poknowledge doorid=27","eqemu_zone_points zone=poknowledge number=11","poknowledge/player.lua:4-8 @ ea0c766"],"unverified":"The script only prints the level-46 message; the block itself is the zone minlevel, which the mirror does not hold. The Seer's waypoint in popGuide is described as \"next to the book\" but is about 150 units from the book door."}
